float rand(vec2 c){
	return fract(sin(dot(c.xy ,vec2(12.9898,78.233))) * 43758.5453);
}

float noise(vec2 p, float freq ){
	float unit = iResolution.x/freq;
	vec2 ij = floor(p/unit);
	vec2 xy = mod(p,unit)/unit;
	//xy = 3.*xy*xy-2.*xy*xy*xy;
	xy = .5*(1.-cos(3.14159*xy));
	float a = rand((ij+vec2(0.,0.)));
	float b = rand((ij+vec2(1.,0.)));
	float c = rand((ij+vec2(0.,1.)));
	float d = rand((ij+vec2(1.,1.)));
	float x1 = mix(a, b, xy.x);
	float x2 = mix(c, d, xy.x);
	return mix(x1, x2, xy.y);
}

float pNoise(vec2 p, int res){
	float persistance = .5;
	float n = 0.;
	float normK = 0.;
	float f = 4.;
	float amp = 1.;
	int iCount = 0;
	for (int i = 0; i<50; i++){
		n+=amp*noise(p, f);
		f*=2.;
		normK+=amp;
		amp*=persistance;
		if (iCount == res) break;
		iCount++;
	}
	float nf = n/normK;
	return nf*nf*nf*nf;
}

// FBM noise function
float fbm(vec2 pos, int octaves, float lacunarity) {
    float value = 0.0;
    float scale = 1.0;

    for(int i = 0; i < octaves; i++) {
        value += pNoise(pos * scale, 3) / scale;
        scale *= lacunarity;
    }

    return value;
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 UV = fragCoord/iResolution.xy;

    UV *= 500.0;

    // Base color
    vec3 baseColor = vec3(0.5);

    // Animate position
    UV += sin(iTime) * 20.3; // Adds some movement

    // Calculate FBM noise for different scales and combine
    float lowNoise = fbm(UV * fbm(UV * 30. + iTime * 20., 9, 2.0) * 199., 6, 2.0);
    float midNoise = fbm(UV * fbm(UV * 10., 9, 2.0), 2, 2.0);
    float highNoise = fbm(UV * fbm(UV * 20., 4, 2.0), 9, 2.0);

    // Combine noise at different scales
    float finalNoise = lowNoise * 0.25 + midNoise * 0.25 + highNoise * 0.5;

    // Distort colors using noise
    vec3 color = baseColor;
    color.rgb += sin(finalNoise * 10.0) * 0.2; // Color distortion
    color.r += sin(iTime + finalNoise * 15.0) * 0.1; // Additional temporal distortion
    color.g += sin(iTime + midNoise * 20.0) * 0.1;
    color.b += sin(highNoise * 25.0) * 0.1;

    // Add some saturation and contrast
    color = clamp(color, 0.0, 1.0);
    color = color * (1.0 - finalNoise * 0.2); // Darken based on noise
    color -= 0.5;
    color *= 3.;

    fragColor = vec4(color, 1.0);
}
